select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, /*(nvl(ee.entrust_amt,0) - nvl(efs.ent_finish_amt,0))/10000 unFinshAmt,*/ (ifnull(ee.entrust_amt,0) - ifnull(efs.ent_finish_amt,0))/10000 unFinshAmt, ir.share_amt/100 as faceValue, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, /*nvl(ir.cprice_amt,ir.share_amt*ibd.unit_cprice) as cpriceAmt, nvl(ir.int_amt,ir.fprice_amt-(ir.share_amt*ibd.unit_cprice)) as intAmt,*/ ifnull(ir.cprice_amt,ir.share_amt*ibd.unit_cprice) as cpriceAmt, ifnull(ir.int_amt,ir.fprice_amt-(ir.share_amt*ibd.unit_cprice)) as intAmt, ir.fprice_amt as fpriceAmt, EE.PRICE_MODEL as priceModel, EE.BUSINESS_MODEL as businessModel, ib.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, ibd.unit_cprice as unitCprice, ibd.yield*100 as yield, ibd.exer_yield*100 as exerYield from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
inner join ibu_quote_bond ib on ir.quote_id=ib.quote_id LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id LEFT JOIN ( select t.entrust_id, sum(t.ent_finish_amt) as ent_finish_amt from ETR_FINISH_STATUS t group by t.entrust_id )efs ON ee.Entrust_Id = efs.entrust_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id left join ( select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, /*nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.yield as yield,*/ ifnull(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.quote_id= #{quoteId,jdbcType=VARCHAR}
union all
/*select ibd.quote_id,wm_concat(ibd.cp_party_id) as cp_party_id,wm_concat(mccic.PARTY_ABBR) as PARTY_ABBR, wm_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader,*/ select ibd.quote_id,group_concat(ibd.cp_party_id) as cp_party_id,group_concat(mccic.PARTY_ABBR) as PARTY_ABBR, group_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader, null as yield, null as unit_cprice, null as exer_yield, null as unit_int, null as unit_fprice, null as cprice_amt, null as int_amt, null as fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status!='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID group by ibd.quote_id union all select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, /*nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,*/ ifnull(su.TRADER_NAME,ibd.cp_trader) cp_trader, ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.trade_status='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} )ibd on ir.quote_id=ibd.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and decode(ib.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})= #{effectiveStatus,jdbcType=VARCHAR} union all select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, /*(nvl(ee.entrust_amt,0) - nvl(efs.ent_finish_amt,0))/10000 unFinshAmt,*/ (ifnull(ee.entrust_amt,0) - ifnull(efs.ent_finish_amt,0))/10000 unFinshAmt, ir.share_amt/100 as faceValue, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, /*nvl(ir.cprice_amt,ir.share_amt*ibd.unit_cprice) as cpriceAmt, nvl(ir.int_amt,ir.fprice_amt-(ir.share_amt*ibd.unit_cprice)) as intAmt,*/ ifnull(ir.cprice_amt,ir.share_amt*ibd.unit_cprice) as cpriceAmt, ifnull(ir.int_amt,ir.fprice_amt-(ir.share_amt*ibd.unit_cprice)) as intAmt, ir.fprice_amt as fpriceAmt, EE.PRICE_MODEL as priceModel, EE.BUSINESS_MODEL as businessModel, ib.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, ibd.unit_cprice as unitCprice, ibd.yield*100 as yield, ibd.exer_yield*100 as exerYield from wfl_ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
inner join wfl_ibu_quote_bond2 ib on ir.quote_id=ib.quote_id LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id LEFT JOIN ( select t.entrust_id, sum(t.ent_finish_amt) as ent_finish_amt from ETR_FINISH_STATUS t group by t.entrust_id )efs ON ee.Entrust_Id = efs.entrust_id left join stl_sec_acct_info stlinfo on ib.sec_manage_acct_id=stlinfo.sec_acct_id left join ( select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, /*nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.yield as yield,*/ ifnull(su.TRADER_NAME,ibd.cp_trader) cp_trader,ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.quote_id= #{quoteId,jdbcType=VARCHAR}
union all
/* select ibd.quote_id,wm_concat(ibd.cp_party_id) as cp_party_id,wm_concat(mccic.PARTY_ABBR) as PARTY_ABBR, wm_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader,*/ select ibd.quote_id,group_concat(ibd.cp_party_id) as cp_party_id,group_concat(mccic.PARTY_ABBR) as PARTY_ABBR, group_concat(nvl(su.TRADER_NAME,ibd.cp_trader)) cp_trader, null as yield, null as unit_cprice, null as exer_yield, null as unit_int, null as unit_fprice, null as cprice_amt, null as int_amt, null as fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status!='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID group by ibd.quote_id union all select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, /*nvl(su.TRADER_NAME,ibd.cp_trader) cp_trader,*/ ifnull(su.TRADER_NAME,ibd.cp_trader) cp_trader, ibd.yield as yield, ibd.unit_cprice, ibd.exer_yield, ibd.unit_int, ibd.unit_fprice, ibd.cprice_amt, ibd.int_amt, ibd.fprice_amt from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id left join MST_CFETS_CUSTOMER_TRADER su on ibd.cp_trader=su.TRADER_ID where ibd.trade_status='07' and ibd.quote_id= #{quoteId,jdbcType=VARCHAR} )ibd on ir.quote_id=ibd.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and #{STATUS_VALID_04}= #{effectiveStatus,jdbcType=VARCHAR}

select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, ir.fprice_amt as tradeAmt, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, ir.int_amt as intAmt, ir.m_trade_amt as mtradeAmt, ir.share_ct_amt as disFaceValue, EE.PRICE_MODEL as priceModel, ic.rate*100 tradeYield from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id left join ibu_quote_crep ic on ir.quote_id=ic.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and decode(ic.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})= #{effectiveStatus,jdbcType=VARCHAR} union all select ir.entrust_id as entrustId, ir.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, ir.fprice_amt as tradeAmt, ir.DEAL_FEE_AMT as trdFeeAmt, ir.SETT_FEE_AMT as settleFeeAmt, ir.int_amt as intAmt, ir.m_trade_amt as mtradeAmt, ir.share_ct_amt as disFaceValue, EE.PRICE_MODEL as priceModel, ic.rate*100 tradeYield from wfl_ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ir.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
LEFT JOIN ETR_ENTRUST ee ON ir.entrust_id = ee.entrust_id left join wfl_ibu_quote_crep ic on ir.quote_id=ic.quote_id where ir.quote_id=#{quoteId,jdbcType=VARCHAR} and #{STATUS_VALID_04}= #{effectiveStatus,jdbcType=VARCHAR}

select * from (select aaa.* from ( select distinct case when match.match_status is null or match.match_status!='01' then '01' when match.match_status ='01' and (match.trd_conf_status is null or match.trd_conf_status='0') then '02' when match.trd_conf_status='1' then '03' end as matchStatus, I.Execid as execid, I.Businesstype as businesstype, fp.finprod_id as finprodId, /*decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO',tr.secid) as finprodMarketId, decode(I.BUSINESSTYPE,'BOND',fp.finprod_abbr,'REPO',null) as finprodAbbr,*/ (case I.BUSINESSTYPE,'BOND' when ts.SECID then 'REPO' else tr.secid end) as finprodMarketId, (case I.BUSINESSTYPE,'BOND' when fp.finprod_abbr then 'REPO'else null end) as finprodAbbr, /*nvl(ts.ps,tr.ps) as ps,*/ ifnull(ts.ps,tr.ps) as ps, /*decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed,*/ (case (case I.BUSINESSTYPE when 'BOND' then ts.SETTLE_SPEED when 'REPO' then tr.SETTLE_SPEED end) when '1' then '01' when '2' then '02' when '3' then '03' end) settleSpeed, /*nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) as secManageAcctId,*/ ifnull(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, ts.prinamt/10000 as faceValue, /*decode(I.BUSINESSTYPE, 'BOND', I.yield2*100, 'REPO', I.PRICE*100) tradeYield,*/ (case I.BUSINESSTYPE when 'BOND' then I.yield2*100 when 'REPO' then I.PRICE*100 end) tradeYield, I.TRADELIMITDAYS as termDays, decode(I.BUSINESSTYPE, 'BOND', I.SETTLCURRAMT, 'REPO', DECODE(I.MARKETINDICATOR, 9, I.TRADECASHAMT, 10, I.SETTLCURRAMT)) as tradeAmt, I.QUOTEID as quoteid,
I.ourinstitutioncode as traderid,
I.OURINSTITUTIONCHINESEFULLNAME as traderidStr,
I.OURTRADERCHINESENAME trader, I.Counterinstitutioncode as counterId,
I.INSTITUTIONCHINESEFULLNAME as counterIdStr,
/*decode(I.Clearingmethod,'13','01','6','02') as clearType, to_char(total.trade_date,'yyyy-MM-dd') as tradeDate, nvl(ts.dealtext,tr.dealtext) as remark*/ (case I.Clearingmethod when '13' then '01' when '6' then '02' end) as clearType, DATE_FORMAT(total.trade_date,'%Y-%m-%dd') as tradeDate, ifnull(ts.dealtext,tr.dealtext) as remark
from INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID left join fin_product fp on ts.SECID=fp.finprod_market_id and fp.finprod_type='F01' LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID
left join stl_sec_acct_info stlinfo /*on nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER)=stlinfo.sec_acct_id*/ on ifnull(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER)=stlinfo.sec_acct_id
left join trdquto_match_info match on I.EXECID=match.exe_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id where 1=1
AND /*nvl(ts.dealdate,tr.dealdate) = #{sysDate,jdbcType=DATE}*/ifnull(ts.dealdate,tr.dealdate) = #{sysDate,jdbcType=DATE}
AND /*nvl(ts.dealdate,tr.dealdate)>= #{startDate,jdbcType=DATE}*/ifnull(ts.dealdate,tr.dealdate)>= #{startDate,jdbcType=DATE}
AND /*nvl(ts.dealdate,tr.dealdate)<=#{endDate,jdbcType=DATE}*/ifnull(ts.dealdate,tr.dealdate)<=#{endDate,jdbcType=DATE}
and su.USER_NAME= #{submitUserId}
AND /*nvl(ts.ps,tr.ps)=#{ps}*/ ifnull(ts.ps,tr.ps)=#{ps}
AND I.Businesstype=#{regAssetType}
AND (/*nvl(ts.SECID,tr.SECID)*/ ifnull(ts.SECID,tr.SECID) in
#{item}
or ts.SECID in
CONCAT(#{item},'.IB')
or fp.finprod_id in
#{item}
)
/* and decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') = #{settleSpeed,jdbcType=VARCHAR}*/ (case (case I.BUSINESSTYPE when 'BOND' then ts.SETTLE_SPEED when 'REPO' then tr.SETTLE_SPEED end) when '1' then '01' when '2' then '02' when '3' then '03' end) = #{settleSpeed,jdbcType=VARCHAR}
AND nvl(ts.OURDEPOSITACCOUNTNUMBER,tr.OURDEPOSITACCOUNTNUMBER) in
#{item}
and I.Execid LIKE CONCAT('%',CONCAT(#{execid},'%'))
and I.QUOTEID LIKE CONCAT('%',CONCAT(#{quoteid},'%'))
AND I.ourinstitutioncode IN
#{item}
AND I.Counterinstitutioncode IN
#{item}
AND (case when match.match_status is null or match.match_status!='01' then '01' when match.match_status ='01' and (match.trd_conf_status is null or match.trd_conf_status='0') then '02' when match.trd_conf_status='1' then '03' end) in
#{item}
) aaa
left join SYS_DATADICT_LIST sdlMatch on aaa.matchStatus=sdlMatch.ITEM_CODE and sdlMatch.DICT_CODE='CSTP_MATCH_STATUS' left join SYS_DATADICT_LIST sdl on aaa.businesstype=sdl.ITEM_CODE and sdl.DICT_CODE='CSTP_BUSINESS_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED' left join SYS_DATADICT_LIST dictct on aaa.clearType=dictct.ITEM_CODE and dictct.DICT_CODE='CLEAR_TYPE'
order by aaa.businesstype, aaa.matchStatus,aaa.ps DESC)
order by ${sort} ${direction}

