  aaa.finprodMarketId),'|'),aaa.finprodAbbr,),'|'),dictquote.ITEM_VALUE),'|'),
  aaa.traderidStr),'|'),aaa.trader),'|'),aaa.counterIdStr),'|'),aaa.counterTrader),'|'),
