  '|' ),aaa.execid ),'|'),aaa.portfolioIds), '|'), aaa.portfolioNames),
  '|' ),aaa.entrustId),'|'),aaa.remark) like CONCAT(CONCAT('%',#{search}),'%')
  or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
  or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or
