union all SELECT distinct decode(T1.is_cancel,'N',#{STATUS_VALID_01},'Y',#{STATUS_VALID_03}) as effectiveStatus, case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END cleanStatus, decode(T1.finprod_type2,'F03',null,nvl(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01})) settleStatus, T1.TOTLE_TRADE_ID totleTradeId, T1.FINPROD_TYPE2 finprodType2, sdl1.item_value finprodType2Str, btm.BUSI_TYPE tgBusiType, sdl2.item_value tgBusiTypeStr, t2.FINPROD_ID AS finprodId, nvl(T2.FINPROD_MARKET_ID,T3.TERM_TYPE) finprodMarketId, T2.FINPROD_ABBR finprodAbbr, T1.PS ps, sdl3.item_value psStr, T1.TRADE_MARKET tradeMarket, sdl4.item_value tradeMarketStr, T1.TRADE_MARKET_MODE tradeMarketMode, sdl6.item_value tradeMarketModeStr, T1.settle_speed as settleSpeed, 'T+'||T1.settle_speed as settleSpeedStr, T1.SEC_MANAGE_ACCT_ID as secManageAcctId, T7.SEC_ACCT_NAME secManageAcctIdStr, decode(T1.finprod_type2,'F01',deal.share_amt/100,null)as faceValue, case when T1.finprod_type2='F01' then decode(nvl(regAdd.CAL_MODE,ibuDet.CALCULATE_FIELD),'01',TO_CHAR(ROUND(T1.unit_cprice,4),'FM990.0000'), '02',TO_CHAR(ROUND(T1.yield*100,4),'FM990.0000') ||'%', '03',TO_CHAR(ROUND(T1.exer_yield*100,4),'FM990.0000')||'%', TO_CHAR(ROUND(T1.yield*100,4),'FM990.0000') ||'%') when T1.finprod_type2 in ('F02','F03') then TO_CHAR(ROUND(T1.rate*100,4),'FM990.0000') ||'%' else null end as tradeYield, T3.term as termDays, deal.trade_Amt tradeAmt, T1.ccy as ccy, sdl7.item_value as ccyStr, to_char(T1.TRADE_DATE,'yyyy-MM-dd') as confirmTradeDate, to_char(T1.SETTLE_DATE,'yyyy-MM-dd') as settleDate, match.exe_id as execid, T1.counter_id as counterId, T6.counter_name counterIdStr, T1.remark, T1.TRADE_DATE as tradeDate, nvl(regAdd.CAL_MODE,ibuDet.CALCULATE_FIELD) as calMode, match.pre_trade_id preTradeId, match.match_status as matchStatus, T1.trader as trader FROM TRD_PRODUCT_TEMP_DEAL_TOTAL T1 inner join ( select td.totle_trade_id,sum(td.share_amt) share_amt, sum(td.trade_amt) as trade_Amt from trd_product_temp_deal td left join trd_product_temp_deal_add tda on td.trade_id=tda.trade_id
INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON tda.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where td.trade_status='01' group by td.totle_trade_id )deal on T1.totle_trade_id=deal.totle_trade_id left join trd_product_temp_deal trd_product_deal on T1.totle_trade_id = trd_product_deal.totle_trade_id LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID left join fin_trade_product T3 on trd_product_deal.FINPROD_ID=T3.finprod_id left join FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE on FIN_PRODUCT_TYPE.FINPROD_ID=trd_product_deal.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T6 ON T1.COUNTER_ID = T6.counter_id LEFT JOIN STL_SEC_ACCT_INFO T7 ON T1.SEC_MANAGE_ACCT_ID = T7.SEC_ACCT_ID LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON T1.TOTLE_TRADE_ID = T8.TRADE_ID LEFT JOIN STL_PAY_ORDERS T9 ON T1.TOTLE_TRADE_ID = T9.TRADE_ID left join trdquto_match_info match on T1.totle_trade_id=match.trd_id LEFT JOIN (select INPUT_VALUE_1 as Finprod_Type_Tg,INPUT_VALUE_2 as ps,OUTPUT_VALUE_1 as busi_type from FIN_PRODUCT_TYPE_CONFIG where CONFIG_TYPE='BUSI_TYPE_MAPPING') btm ON FIN_PRODUCT_TYPE.TYPE_8 = btm.Finprod_Type_Tg AND T1.Ps = btm.ps LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='PINAN_ASSET_TYPE' and sdl1.item_code = FIN_PRODUCT_TYPE.TYPE_8 LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='BUSI_TYPE_POSITION' and sdl2.item_code = btm.BUSI_TYPE LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='PS' and sdl3.item_code = T1.PS LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='TRADE_PLACE' and sdl4.item_code = T1.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl6 on sdl6.dict_code ='SHARES_TRADE_MARKET' and sdl6.item_code = T1.TRADE_MARKET_MODE LEFT JOIN SYS_DATADICT_LIST sdl7 on sdl7.dict_code ='CCY' and sdl7.item_code = T1.ccy left join reg_fin_product_deal_total_add regAdd on regAdd.totle_trade_id=nvl(match.PRE_TRADE_ID,T1.B_TRADE_ID) left join ibu_quote_bond_det ibuDet on ibuDet.QUOTE_ID=nvl(match.PRE_TRADE_ID,T1.B_TRADE_ID) and ibuDet.TRADE_STATUS='07' WHERE T1.trade_status='01' and T1.FINPROD_TYPE2 in ('F01','F02','F03') and T1.ps in ('T01','T02','T03','03','04') and (T8.SETTLE