like '%' || #{search} || '%')*/
(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(concat(
sdles.ITEM_VALUE,'|'),sdlcs.ITEM_VALUE),'|'),sdlss.ITEM_VALUE),'|'),
aaa.totleTradeId),'|'),aaa.finprodType2Str),'|'),aaa.tgBusiTypeStr),'|'),
aaa.finprodMarketId),'|'),aaa.finprodAbbr,),'|'),aaa.psSt),'|'),
aaa.tradeMarketStr),'|'),aaa.tradeMarketModeStr),'|'),aaa.settleSpeedStr),'|'),aaa.secManageAcctIdStr),'|'),
aaa.ccyStr),'|'),aaa.execid),'|'),aaa.counterIdStr),'|'),aaa.remark) like CONCAT(CONCAT('%',#{search}),'%')

or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
or aaa.tradeYield=#{search} or  /*aaa.tradeYield =#{search}||'%'*/CONCAT(aaa.tradeYield,'')=#{search}
or /*aaa.termDays||'' =#{search}*/CONCAT(aaa.termDays,'')=#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or /*aaa.confirmTradeDate||'' =#{search}*/ CONCAT(aaa.confirmTradeDate,'')=#{search}
or /*aaa.confirmTradeDate||''=#{year}||'-'||#{search}*/CONCAT(aaa.confirmTradeDate,'')=CONCAT(CONCAT(#{year},'-'),#{search})
or /*replace(aaa.confirmTradeDate,'-','/')||''=#{search}*/CONCAT(replace(aaa.confirmTradeDate,'-','/'),'') =#{search}
or /*replace(aaa.confirmTradeDate,'-','/')||''=#{year}||'/'||#{search}*/CONCAT(replace(aaa.confirmTradeDate,'-','/'),'') =CONCAT(CONCAT(#{year},'/'),#{search})
or /*aaa.settleDate||'' =#{search}*/CONCAT(aaa.settleDate,'')=#{search}
or /*aaa.settleDate||''=#{year}||'-'||#{search}*/CONCAT(aaa.settleDate,'')=CONCAT(CONCAT(#{year},'-'),#{search})
or /*replace(aaa.settleDate,'-','/')||''=#{search}*/ CONCAT(replace(aaa.settleDate,'-','/'),'') =#{search}
or /*replace(aaa.settleDate,'-','/')||''=#{year}||'/'||#{search}*/ CONCAT(replace(aaa.settleDate,'-','/'),'') =CONCAT(CONCAT(#{year},'/'),#{search})
