SELECT ROWNUM rowNums, TPDA.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, TPD.SHARE_AMT/100 QTYD, TPD.PRIN_AMT prinAmtTheoryd, TPD.INT_AMT intAmtTheoryd, TPD.CPRICE_AMT cpriceAmt, TPD.INT_AMT intAmt, TPD.FPRICE_AMT fpriceAmt, ttft.fee_amt jyFeeAmt, ttft1.fee_amt jsFeeAmt, TPD.TRADE_AMT tradeAmt, TPDA.Entrust_Id entrustId, EE.PRICE_MODEL priceModel, /*(nvl(ee.entrust_amt,0) - nvl(efs.ent_finish_amt,0))/10000 unFinshAmt,*/ (ifnull(ee.entrust_amt,0) - ifnull(efs.ent_finish_amt,0))/10000 unFinshAmt, ssai.sec_acct_name secAcctId, TPD.YIELD*100 matureYield, TPD.EXER_YIELD*100 exeYield, EE.BUSINESS_MODEL busiTypePosition, TPD.UNIT_CPRICE unitPrice, ftp.m_int_amt as mintAmt, ftp.m_trade_amt as mtradeAmt, pledges.disFaceValue as disFaceValue, ftp.int_rate*100 as rate FROM TRD_PRODUCT_DEAL TPD INNER JOIN TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON TPDA.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userName}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = TPDA.PORTFOLIO_ID LEFT JOIN TRD_TRADE_FEE_DETAIL ttft ON tpd.trade_id = ttft.trade_id AND ttft.fee_type =#{feeType06} LEFT JOIN TRD_TRADE_FEE_DETAIL ttft1 ON tpd.trade_id = ttft1.trade_id AND ttft1.fee_type =#{feeType08} LEFT JOIN ETR_ENTRUST ee ON TPDA.Entrust_Id = ee.entrust_id LEFT JOIN ETR_FINISH_STATUS efs ON ee.Entrust_Id = efs.entrust_id AND TPD.TRADE_ID = efs.trade_id LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpd.sec_manage_acct_id = ssai.SEC_ACCT_ID left join fin_trade_product ftp on ftp.finprod_id=TPD.TRADE_ID left join (select pledge.finprod_id,sum(pledge.pledge_number*pledge.pledge_ratio*100) as disFaceValue from FIN_DEAL_PLEDGE pledge group by pledge.finprod_id)pledges on ftp.finprod_id=pledges.finprod_id where TPD.TOTLE_TRADE_ID = #{totleTradeId} and TPD.Trade_Status='01'
and TPD.TRADE_ID=#{busiCode}

select sum(t.qty) from (
    select count(*) qty from wfl_reg_fin_product_deal_total  where TOTLE_TRADE_ID=#{tradeId,jdbcType=VARCHAR}
    union all
    select count(*) qty from reg_fin_product_deal_total  where TOTLE_TRADE_ID=#{tradeId,jdbcType=VARCHAR}
) t

